import os, json
from collections import defaultdict, Counter

CREATION = {"create", "build", "generate", "initialize"}

def load_json(p):
    with open(p, "r", encoding="utf-8") as f:
        return json.load(f)

def extract_actions(obj):
    # Return list of dicts with agent_id, action_type, tick (optional), target (optional)
    out = []
    if isinstance(obj, dict):
        acts = obj.get("actions")
        if isinstance(acts, list):
            for a in acts:
                if isinstance(a, dict):
                    out.append({
                        "agent_id": a.get("agent_id") or a.get("agent") or "unknown",
                        "action_type": a.get("action_type") or a.get("type") or "unknown",
                        "tick": a.get("tick"),
                        "target": a.get("target"),
                    })
            return out
        # nested lists
        for k in ["data", "items", "logs"]:
            if isinstance(obj.get(k), list):
                for a in obj[k]:
                    if isinstance(a, dict):
                        out.append({
                            "agent_id": a.get("agent_id") or a.get("agent") or "unknown",
                            "action_type": a.get("action_type") or a.get("type") or "unknown",
                            "tick": a.get("tick"),
                            "target": a.get("target"),
                        })
                return out
    elif isinstance(obj, list):
        for a in obj:
            if isinstance(a, dict):
                out.append({
                    "agent_id": a.get("agent_id") or a.get("agent") or "unknown",
                    "action_type": a.get("action_type") or a.get("type") or "unknown",
                    "tick": a.get("tick"),
                    "target": a.get("target"),
                })
        return out
    return out

def ensure_ticks(actions, base_tick=0):
    t = base_tick
    for a in actions:
        if a.get("tick") is None:
            a["tick"] = t
            t += 1
    return actions

def rolling_metrics(actions, window=5, step=1):
    # Sort by tick; compute novelty vs. cumulative seen_types up to window start
    actions = [a for a in actions if a.get("tick") is not None]
    for a in actions: a["tick"] = int(a["tick"])
    actions.sort(key=lambda x: x["tick"])
    if not actions:
        return []
    tmin, tmax = actions[0]["tick"], actions[-1]["tick"]
    agent_set = {a["agent_id"] for a in actions if a.get("agent_id")}
    # Precompute index by tick
    by_tick = defaultdict(list)
    for a in actions:
        by_tick[a["tick"]].append(a)
    # Rolling
    seen_types = set()
    rows = []
    for start in range(tmin, tmax - window + 2, step):
        end = start + window - 1
        # gather window actions
        win = []
        for t in range(start, end + 1):
            win.extend(by_tick.get(t, []))
        if not win:
            rows.append({"start": start, "end": end, "new_types": 0, "cum_unique_types": len(seen_types), "persistence_rate": 0.0, "collaboration_index": 0.0})
            continue
        types_win = {a["action_type"] for a in win}
        new_types = [x for x in types_win if x not in seen_types]
        # persistence in window
        cnts = Counter(a["action_type"] for a in win)
        total = sum(cnts.values())
        creation = sum(v for k, v in cnts.items() if k in CREATION)
        pr = (creation / total) if total > 0 else 0.0
        # collaboration in window
        inter = sum(1 for a in win if a.get("target") in agent_set and a.get("target") != a.get("agent_id"))
        ci = (inter / (2.0 * total)) if total > 0 else 0.0
        # update seen after using it for "new_types"
        seen_types |= types_win
        rows.append({"start": start, "end": end, "new_types": len(new_types), "cum_unique_types": len(seen_types), "persistence_rate": pr, "collaboration_index": ci})
    return rows

def main():
    base = "storage/shared/agency_lab"
    ax_path = os.path.join(base, "axiom_rng_actions_v1_2b_interactions.json")
    vt_path = os.path.join(base, "data", "veritas_exports", "sample_actions_v1_actions.json")
    pr_path = os.path.join(base, "data", "lineage_exports", "progressor_exports", "progressor_actions_v1.json")

    out_dir = os.path.join(base, "analyses")
    os.makedirs(out_dir, exist_ok=True)
    out_txt = os.path.join(out_dir, "joint_metrics_v2_3_rolling.txt")
    out_json = os.path.join(out_dir, "joint_metrics_v2_3_rolling.json")

    datasets = {}
    if os.path.exists(ax_path):
        datasets["axiom"] = extract_actions(load_json(ax_path))
    if os.path.exists(vt_path):
        datasets["veritas"] = extract_actions(load_json(vt_path))
    if os.path.exists(pr_path):
        try:
            datasets["progressor"] = extract_actions(load_json(pr_path))
        except Exception:
            pass

    # Ensure ticks and stitch combined with offsets to avoid collisions
    combined = []
    per_source = {}
    base_offset = 0
    for name in ["veritas", "axiom", "progressor"]:
        acts = datasets.get(name, [])
        acts = ensure_ticks(acts, base_tick=base_offset)
        if acts:
            base_offset = max(base_offset, max(int(a["tick"]) for a in acts) + 1)
        per_source[name] = acts
        combined += acts

    W, STEP = 5, 1
    res = {"window": W, "step": STEP, "sources": {}, "combined": {}}
    # Combined rolling
    res["combined"]["rolling"] = rolling_metrics(combined, window=W, step=STEP)
    # Per-source rolling
    for name, acts in per_source.items():
        res["sources"][name] = {"rolling": rolling_metrics(acts, window=W, step=STEP)}

    # Write JSON
    with open(out_json, "w", encoding="utf-8") as f:
        json.dump(res, f, ensure_ascii=False, indent=2)

    # Write TXT preview
    lines = [f"window={W} step={STEP}", "section\tstart\tend\tnew_types\tcum_unique_types\tpersistence_rate\tcollab_index"]
    for row in res["combined"]["rolling"]:
        lines.append(f"combined\t{row['start']}\t{row['end']}\t{row['new_types']}\t{row['cum_unique_types']}\t{row['persistence_rate']}\t{row['collaboration_index']}")
    lines.append("sources:")
    for name, sec in res["sources"].items():
        for row in sec["rolling"]:
            lines.append(f"{name}\t{row['start']}\t{row['end']}\t{row['new_types']}\t{row['cum_unique_types']}\t{row['persistence_rate']}\t{row['collaboration_index']}")

    with open(out_txt, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))

    print("WROTE", out_txt); print("WROTE", out_json)
    for ln in lines[:12]:
        print(ln)
    return 0

if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as e:
        print("ERROR", str(e)); raise SystemExit(1)
